/**
 * Everything the Web UI knows about a marker that should be created.
 *
 * `position` is in the map projection (the same coordinate system the marker
 * layer uses for its features).
 */
export interface MarkerCreationData {
    /** Internal unique marker name. Generated by the game when omitted. */
    name?: string;
    /** User-visible marker name/label. Sent as the marker text. */
    label: string;
    /** Marker text. Takes precedence over `label` when set. */
    text?: string;
    /** CfgMarkers class name. */
    type: string;
    /** CfgMarkerColors class name. */
    color: string;
    /** Map position as [x, y]. */
    position: [number, number];
    /** Marker direction in degrees. */
    dir?: number;
    /** Marker shape. */
    shape?: 'ICON' | 'RECTANGLE' | 'ELLIPSE' | 'POLYLINE';
    /** Marker opacity, 0..1. */
    alpha?: number;
    /** CfgMarkerBrushes class name. */
    brush?: string;
    /** Marker size, either a uniform scale or [width, height]. */
    size?: number | [number, number];
    /** Marker channel. Not yet configurable in the UI; defaults to 0 (global). */
    channel?: number;
    /** Polyline points as a flat list: [x1, y1, x2, y2, ...]. */
    polyline?: number[];
}

/**
 * Sends a newly created marker to the game.
 *
 * The game generates a unique internal marker name when `name` is omitted and
 * returns it in the response. That name has to be used when the marker is
 * updated later.
 */
export function createMarker(marker: MarkerCreationData): Promise<{ name: string }> {
    return window.Networking.Request({
        a: 'ACE_TacPhone_Map',
        c: 'CreateMarker',
        marker: {
            ...marker,
            channel: marker.channel ?? 0, // TODO: make configurable in the Web UI
        },
    }).then((result) => {
        const name = (result as { name?: unknown }).name;
        if (typeof name !== 'string') {
            throw new Error('Game did not return a marker name');
        }
        return { name };
    });
}

/**
 * Updates an existing marker.
 *
 * The payload is sent through the same command as `createMarker`: the game
 * treats a known marker name as an update and only applies the fields that are
 * present, so callers can send a single changed property.
 */
export function updateMarker(
    name: string,
    changes: Omit<Partial<MarkerCreationData>, 'name'>,
): Promise<void> {
    return window.Networking.Request({
        a: 'ACE_TacPhone_Map',
        c: 'CreateMarker',
        marker: {
            ...changes,
            name,
        },
    }).then(() => undefined);
}

/**
 * Moves an existing marker to a new position.
 *
 * This is a position-only payload sent to the same command as `createMarker`:
 * the game treats a known marker name as an update instead of creating a
 * second marker.
 */
export function updateMarkerPosition(name: string, position: [number, number]): Promise<void> {
    return updateMarker(name, { position });
}

/**
 * Deletes a marker in the game. `name` is the internal marker name returned by
 * `createMarker`, not the user-visible label.
 */
export function deleteMarker(name: string): Promise<void> {
    return window.Networking.Request({
        a: 'ACE_TacPhone_Map',
        c: 'DeleteMarker',
        marker: name,
    }).then(() => undefined);
}
